const fs=require('node:fs'),vm=require('node:vm'),assert=require('node:assert/strict');const w={};vm.runInNewContext(fs.readFileSync('custom-calculator-core-20261102.js','utf8'),w);const C=w.MT_CUSTOM_CALCULATORS;let checks=0;const calc=(expression,values={x:2})=>C.evaluate(C.compile(expression,Object.keys(values)),values),eq=(a,b)=>{checks++;assert.ok(Math.abs(a-b)<1e-12*Math.max(1,Math.abs(b)),a+' != '+b);};
eq(calc('2+3*4'),14);eq(calc('3×2−4÷2'),4);assert.equal(C.parseFile('{"version":1,"calculators":[]}').length,0);eq(calc('(2+3)*4'),20);eq(calc('-2^2'),-4);eq(calc('2^-2'),.25);eq(calc('2^3^2'),512);eq(calc('1,5*x'),3);eq(calc('max(1,5;2;3)'),3);eq(calc('sin(pi/2)+ln(e)'),2);eq(calc('sqrt(3)*440*100*0.8/1000'),60.968188426424486);eq(calc('150*30/(600*.85)'),8.823529411764707);eq(C.number('1,2e3'),1200);
for(const expression of ['x.constructor','window','fetch(1)','alert(1)','__proto__','x=1','[1]','1;2','sqrt(-1)','1/0','(-1)^.5','exp(1000)','1e101','2^10001','min(1)','sqrt(1;2)','sin()','1+','1 2','1,2,3','('.repeat(40)+'1'+')'.repeat(40),'1+'.repeat(300)+'1']){assert.throws(()=>calc(expression),expression);checks++;}
const d={name:'Hydraulic',expression:'pressure*flow/(600*efficiency)',output:'Power',unit:'kW',variables:[{name:'pressure',label:'Pressure',unit:'bar',value:150},{name:'flow',label:'Flow',unit:'L/min',value:30},{name:'efficiency',label:'Efficiency',unit:'',value:.85}]};eq(C.calculate(d).value,8.823529411764707);const bytes=JSON.stringify({version:1,calculators:[d]});assert.equal(JSON.stringify(C.parseFile(bytes)[0]),JSON.stringify(d));
for(const data of [{version:2,calculators:[d]},{version:1,calculators:[{...d,script:'run'}]},{version:1,calculators:[{...d,variables:[{name:'constructor',label:'x',unit:'',value:1}]}]},{version:1,calculators:Array(51).fill(d)},{version:1,calculators:[{...d,variables:[...d.variables,d.variables[0]]}]}]){assert.throws(()=>C.parseFile(JSON.stringify(data)));checks++;}
